// Netlify Edge Functions (Deno).  The module's bytes are embedded (wasm-bytes.js, generated by the packager): an edge function
// cannot read files next to it.  State is in memory per instance.
import bytes from "../../wasm-bytes.js";
import { createServer } from "../../runtime/server.js";
import { memoryStore } from "../../runtime/stores.js";
import { assets } from "../../runtime/assets.js";

const app = createServer({ module: bytes, hostName: "netlify-edge", store: memoryStore(), assets });
export default (request) => app.fetch(request);
// everything but the function variant
export const config = { path: "/*", excludedPath: ["/fn", "/fn/*"] };
